module.exports = function (RED) {
    "use strict";

    function CompositionNode(n) {
        RED.nodes.createNode(this, n);
        var node = this;

        this.compositionName = n.compositionName;          // id
        this.compositionNameLabel = n.compositionNameLabel; // name
        this.description = n.description;                  // 新增: 描述
        this.projectId = n.projectId;

        try {
            // 如果配置界面传过来的是 JSON 字符串，则解析它
            this.params = n.nodeParams ? JSON.parse(n.nodeParams) : [];
        } catch (err) {
            // 如果解析出错（例如格式不对），设为空数组并打印错误
            this.params = [];
            node.error("解析参数列表失败: " + err);
        }

        // 发送整个 flow 给后端
        let flowNodes = [];
        RED.nodes.eachNode(function (n) {
            flowNodes.push(n);
        });
        let flowJson = JSON.stringify(flowNodes, null, 2);

        /* fetch('http://127.0.0.1:8080/api/services/uploadservice', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: flowJson
        }); */

        // 同时把 composition 信息输出
        this.on("input", function(msg, send, done) {
            msg = msg || {};
            msg.compositionId = node.compositionName;           // id
            msg.compositionName = node.compositionNameLabel;    // name
            msg.description = node.description;                 // 描述
            msg.projectId = node.projectId;
            msg.nodeParams = node.params;                       //参数列表

            send(msg);
            done();
        });
    }

    RED.nodes.registerType("Composition", CompositionNode);

    RED.httpAdmin.post('/composition/handle-deploy', RED.auth.needsPermission('composition.write'), function(req, res) {
        try {
            console.log('[Composition Runtime] 接收到部署数据:', req.body);

            // 6. 在这里接收到前端传来的 JSON
            // 执行最终的数据库存储逻辑
            // saveToDatabase(req.body);

            res.status(200).send("Success");
        } catch (err) {
            res.status(500).send(err.toString());
        }
    });
};
